pub fn run<'a>(
    config: &'a aws_config::SdkConfig,
    operation: &'a str,
    input: &'a Value,
    options: &'a Options,
) -> core::CommandFuture<'a> {
    Box::pin(async move {
        let mut config = aws_sdk_bedrockruntime::config::Builder::from(config);
        if let Some(endpoint) = &options.endpoint_url {
            config = config.endpoint_url(endpoint);
        }
        let client = aws_sdk_bedrockruntime::Client::from_conf(config.build());
        let output = Output::new(options.clone());
        let command: core::CommandFuture<'_> = match operation {
            "apply_guardrail" => Box::pin(call_apply_guardrail(&client, input, &output)),
            "converse" => Box::pin(call_converse(&client, input, &output)),
            "converse_stream" => Box::pin(call_converse_stream(&client, input, &output)),
            "count_tokens" => Box::pin(call_count_tokens(&client, input, &output)),
            "get_async_invoke" => Box::pin(call_get_async_invoke(&client, input, &output)),
            "invoke_guardrail_checks" => {
                Box::pin(call_invoke_guardrail_checks(&client, input, &output))
            }
            "invoke_model" => Box::pin(call_invoke_model(&client, input, &output)),
            "invoke_model_with_bidirectional_stream" => Box::pin(
                call_invoke_model_with_bidirectional_stream(&client, input, &output),
            ),
            "invoke_model_with_response_stream" => Box::pin(
                call_invoke_model_with_response_stream(&client, input, &output),
            ),
            "list_async_invokes" => Box::pin(call_list_async_invokes(&client, input, &output)),
            "start_async_invoke" => Box::pin(call_start_async_invoke(&client, input, &output)),
            _ => return Err(CliError::input(format!("unknown operation: {operation}"))),
        };
        command
            .await
            .map_err(|error| error.context("bedrock-runtime", operation))
    })
}
